  kitc = nil, nameR = nil, zoneLogs = 0,   -- the drawn kit (global: centre, half sizes), the team name plate's right edge
  zoneOff = {},                   -- header layer -> true while CHD.HeaderZones holds its pointer zone off
  hfocus = nil, hfocusLogs = 0,   -- the header item holding the focus (logged once per change)
  atdf = {x = 0, y = 0, s = 1, wait = 0, n = 0},   -- the AT / DF layer's local pos / scale as last sent
}

local function CHD_Cmd(...)
  if type(funcLuaMenuCommand) == "function" then
    return pcall(funcLuaMenuCommand, ...)
  end
  return false
end

local function CHD_Get(...)
  local ok, v = CHD_Cmd(...)
  if ok then
    return v
  end
  return nil
end

local function CHD_Lc(...)
  if type(funcLuaCommand) == "function" then
    local ok, v = pcall(funcLuaCommand, ...)
    if ok then
      return v
    end
  end
  return nil
end

local function CHD_Log(msg)
  CHD_Lc(CHD.LOG, "EVT dock_panel " .. msg)
end

local function CHD_Pack(...)
  return {n = select("#", ...), ...}
end

local function CHD_PanelOn()
  return EVT_CHD_PANEL == true and EVT_UI_PRESET ~= "off"
end

-- BetterUI 1.21.9 (owner 2026-10-13): the TÁCTICAS block (title + the 3 tactic plates) stays as in the original game:
-- no tactics row, no slices / scissor, no tactics focus re-routing; the rest of the panel layout is unchanged.
local function CHD_TacOn()
  return CHD_PanelOn() and EVT_CHD_TACTICS == true
end

local function CHD_ClipOn()
  return CHD_TacOn() and EVT_CHD_CLIP == true
end

local function CHD_ArrowsOn()
  return EVT_CHD_ARROWS == true and EVT_UI_PRESET ~= "off"
end

local function CHD_AtdfOn()
  return CHD_PanelOn() and EVT_CHD_ATDF == true
end

-- the AT / DF layer's transform as recorded (absolute: sending it again changes nothing)
local function CHD_AtdfSend()
  local st = CHD.atdf
  CHD_Cmd(CHD.LAYER_SCALE, CHD_ATDF.layer, st.s, st.s, 1, 0)
  CHD_Cmd(CHD.LAYER_POS, CHD_ATDF.layer, st.x, st.y, 0, 0)
end

-- ---- layout ------------------------------------------------------------------------------------------------------------
local CHD_ATC_TACTICS = 727258178   -- _atc_tactics01: the frame locator of the TÁCTICAS block

local function CHD_Place(layer, idx, rows, skip)
  for _, r in ipairs(rows) do
    if r[1] ~= skip then
      CHD_Cmd(CHD.NODE_POS, layer, idx, r[1], 0, r[2])
      CHD_Cmd(CHD.NODE_POS, layer, idx, r[1], 1, r[3])
      if r[4] ~= nil then
        CHD_Cmd(CHD.NODE_SCALE, layer, idx, r[1], r[4], r[5])
      end
    end
  end
end

local function CHD_HideCmdText(idx)
  CHD_Cmd(CHD.SET_TEXT, CHD.CMD, CHD.TEXT_CMD, "", idx)
  CHD_Cmd(CHD.NODE_VIS, CHD.CMD, CHD.TEXT_CMD, false, idx)
end

local function CHD_HideConfText()
  CHD_Cmd(CHD.TEXT_VIS, CHD.CONF, CHD.TEXT_BUILD, false, 0)
  CHD_Cmd(CHD.NODE_VIS, CHD.CONF, CHD.TEXT_BUILD, false, 0)
end

-- the kit's frame locator (absolute frame units), as placed last
local function CHD_KitAtc(frame)
  if CHD.kit[frame] == nil then
    for _, r in ipairs(CHD_FRAME[frame]) do
      if r[1] == CHD.ATC_UNI then
        CHD.kit[frame] = {r[2], r[3]}
      end
    end
  end
  return CHD.kit[frame]
end

-- panel mode: the kit's frame locator. With the team editor's icon row and its list off screen (spec.icons +
-- hide_list) the row and another mod's button take the EQUIPACIÓN place under the panel, so the kit goes to the
-- list's free column on its left, on the same row
local CHD_UNI_ASIDE_DX = -445.0
local function CHD_UniPanel(frame)
  local k = CHD_UNI_PANEL[frame]
  if k == nil then
    return nil
  end
  local I = CHD.Icons()
  if I.n > 0 and I.hide then
    return {k[1] + CHD_UNI_ASIDE_DX, k[2]}
  end
  return k
end

-- the header layers in a mode: "header" = crest | team name | kit | player plate | «Nv.»; "panel" = retail header,
-- the kit as the retail EQUIPACIÓN box under the panel
local function CHD_ApplyHeader(layer, mode)
  local hdr = mode == "header"
  if layer == CHD.UNI then
    if hdr then
      CHD_Place(layer, 0, CHD_UNI)
      CHD_Cmd(CHD.SET_PRIO, layer, 0, CHD.KIT_PRIO)
    else
      CHD_Place(layer, 0, CHD_UNI_RETAIL)
    end
    for _, n in ipairs(CHD_UNI_HIDE) do
      CHD_Cmd(CHD.NODE_VIS, layer, n, not hdr, 0)
    end
    CHD_Cmd(CHD.MESH_VIS, layer, CHD.KIT_SHADOW, not hdr, 0)
  elseif layer == CHD.BAR then
    if hdr then
      CHD_Place(layer, 0, CHD_BAR)
      CHD_Cmd(CHD.SWAP, layer, CHD_HDR.nv_atlas, CHD_HDR.nv_sprite, CHD_HDR.nv_slot, 0, 0)
      -- round 8: the white card «Nv.» in the level digits' blue, fully opaque
      local c = CHD_HDR.nv_rgb
      CHD_Cmd(CHD.PRIM_COLOR, layer, 0, CHD_HDR.nv_mesh, c[1], c[2], c[3])
      CHD_Cmd(CHD.PRIM_ALPHA, layer, 0, CHD_HDR.nv_mesh, 1)
    else
      CHD_Place(layer, 0, CHD_BAR_RETAIL)
      CHD_Cmd(CHD.SWAP, layer, CHD_HDR_CHECK.nv_atlas, CHD_HDR.nv_slot, CHD_HDR.nv_slot, 0, 0)
      CHD_Cmd(CHD.PRIM_COLOR, layer, 0, CHD_HDR.nv_mesh, 1, 1, 1)   -- the retail label carries its own blue
    end
  elseif layer == CHD.NAME then
    CHD_Place(layer, 0, hdr and CHD_NAME or CHD_NAME_RETAIL)
  end
end

-- every node edit of one layer instance (absolute values: applying it again changes nothing)
local function CHD_Apply(layer, idx)
  idx = idx or 0
  if CHD_PanelOn() then
    if CHD_FRAME[layer] ~= nil then
      if idx == 0 then
        CHD_Place(layer, 0, CHD_FRAME[layer], (not CHD_TacOn()) and CHD_ATC_TACTICS or nil)
        local k = CHD.hdr == "header" and CHD_KitAtc(layer) or CHD_UniPanel(layer)
        if k ~= nil then
          CHD_Cmd(CHD.NODE_POS, layer, 0, CHD.ATC_UNI, 0, k[1])
          CHD_Cmd(CHD.NODE_POS, layer, 0, CHD.ATC_UNI, 1, k[2])
        end
      end
    elseif layer == CHD.BASE then
      if CHD_TacOn() then
        CHD_Place(layer, 0, CHD_BASE)
      end
    elseif layer == CHD.CMD then
      if not CHD_TacOn() then
        return
      end
      if idx <= 2 then
        CHD_Place(layer, idx, CHD_ClipOn() and CHD_CMD_CLIP[idx] or CHD_CMD_BOX)
        CHD_HideCmdText(idx)
        if not CHD_ClipOn() and CHD_Lc(CHD.SLICES_READY) == true then
          CHD_Cmd(CHD.SWAP, layer, CHD.SLICE_ATLAS, CHD.SLICES[idx], CHD.PLATE_SLOT, 0, idx)
        end
      end
    elseif layer == CHD.TAC then
      if idx <= 2 and CHD_TacOn() then
        CHD_Place(layer, idx, CHD_FOCUS)
      end
    elseif layer == CHD.FORM then
      CHD_Place(layer, 0, CHD_FORM)
    elseif layer == CHD.CONF then
      CHD_Place(layer, 0, CHD_CONF)
      CHD_HideConfText()
    elseif (layer == CHD.UNI or layer == CHD.BAR or layer == CHD.NAME) and CHD.hdr ~= nil then
      CHD_ApplyHeader(layer, CHD.hdr)
    end
  end
  if layer == CHD_ATDF.layer and (CHD.atdf.x ~= 0 or CHD.atdf.y ~= 0 or CHD.atdf.s ~= 1) then
    CHD_AtdfSend()                -- keep the engine on the recorded transform (Step corrects it from there)
  end
  if layer == CHD.DOCKNO and CHD_ArrowsOn() then
    CHD_Place(layer, 0, CHD_DOCKNO)
  end
  if not CHD.logged and (CHD_PanelOn() or CHD_ArrowsOn()) then
    CHD.logged = true
    CHD_Log("on (panel " .. tostring(CHD_PanelOn()) .. ", clip " .. tostring(CHD_ClipOn()) .. ", arrows "
      .. tostring(CHD_ArrowsOn()) .. ")")
  end
end

-- every Step: each box's plate clipped to its box (the box's frame layer recomputes its rectangle first: the dock's
-- slide-in / dock switch move them)
local CHD_G
local function CHD_Clip()
  for i = 0, 2 do
    if CHD_Get(CHD.IS_OPEN, CHD.CMD, i) == true and CHD_Get(CHD.IS_OPEN, CHD.TAC, i) == true then
      -- the frame must be somewhere on screen, else the box is left unclipped
      local fx, fy = CHD_G(CHD.TAC, i, CHD.TOUCH_LIST)
      if not CHD.clipLogged then
        CHD_Log("clip box " .. i .. " frame at " .. tostring(fx) .. "," .. tostring(fy))
        if i == 2 then
          CHD.clipLogged = true
        end
      end
      if fx ~= nil and math.abs(fx) < 4096 and math.abs(fy) < 4096 then
        CHD_Cmd(CHD.SCISSOR_UPDATE, CHD.TAC, i)
        CHD_Cmd(CHD.SCISSOR_COPY, CHD.CMD, i, CHD.TAC, i)
        CHD_Cmd(CHD.SCISSOR_ON, CHD.CMD, i, true)
      else
        CHD_Cmd(CHD.SCISSOR_ON, CHD.CMD, i, false)
      end
    end
  end
end

CHD_G = function(layer, idx, node)
  local ok, x, y = CHD_Cmd(CHD.GPOS, layer, idx, node)
  if ok and type(x) == "number" and type(y) == "number" then
    return x, y
  end
  return nil
end

-- every Step: the kit's centre onto its place between the team name and player plates, measured in global units (the bar's and the field's
-- scales come from known node distances, so another mod scaling / moving the pitch or the bar changes nothing)
local function CHD_FixKit()
  if CHD.hdr ~= "header" or CHD_Get(CHD.IS_OPEN, CHD.BAR, 0) ~= true or CHD_Get(CHD.IS_OPEN, CHD.UNI, 0) ~= true then
    return
  end
  local bx, by = CHD_G(CHD.BAR, 0, CHD.POS_BASE)
  local ex, ey = CHD_G(CHD.BAR, 0, CHD_HDR.crest)
  local ux, uy = CHD_G(CHD.UNI, 0, CHD.POS_BASE)
  local ix, iy = CHD_G(CHD.UNI, 0, CHD.KIT_ICON)
  if bx == nil or ex == nil or ux == nil or ix == nil then
    return
  end
  local cr = CHD_BAR_CREST
  local kbx, kby = (ex - bx) / cr[1], (ey - by) / cr[2]
  local kux, kuy = (ix - ux) / CHD_UNI[1][2], (iy - uy) / CHD_UNI[1][3]
  if math.abs(kbx) < 0.05 or math.abs(kby) < 0.05 or math.abs(kux) < 0.05 or math.abs(kuy) < 0.05 then
    return
  end
  -- where the kit is drawn now (global units: centre, half sizes of its focus frame), for the pointer guard
  CHD.kitc = {ux + CHD_HDR.ux * kux, uy + CHD_HDR.uy * kuy, CHD_UNI[3][4] / 2 * math.abs(kux),
    CHD_UNI[3][5] / 2 * math.abs(kuy)}
  -- the kit's centre: midway between the measured team name plate's right edge and the player plate's left edge
  -- (where the retail «Nv. EQUIPO» sat), in bar units; the layout's value only while the plates are not measurable
  local kx = CHD_HDR.kx
  local nx = CHD_G(CHD.NAME, 0, CHD.NAME_BASE)
  local px = CHD_G(CHD.DECK, 0, CHD.DECK_BASE)
  CHD.nameR = nx ~= nil and nx + CHD_NAME[1][4] * kbx or nil   -- the drawn team name plate's right edge (global)
  if nx ~= nil and px ~= nil then
    local gl, gr = (nx - bx) / kbx + CHD_NAME[1][4], (px - bx) / kbx
    if gr > gl and gr - gl < 600 then
      kx = (gl + gr) / 2
    end
  end
  -- the kit's centre (CHD_HDR.ux / uy in its layer: the retail hit zone's centre) onto the target, so the layer
  -- origin goes there minus that offset
  local tx, ty = bx + kx * kbx - CHD_HDR.ux * kux, by + CHD_HDR.ky * kby - CHD_HDR.uy * kuy
  local dx, dy = (tx - ux) / kux, (ty - uy) / kuy
  if math.abs(dx) < 0.5 and math.abs(dy) < 0.5 then
    return
  end
  for _, frame in ipairs(CHD.FRAMES) do
    if CHD_Get(CHD.IS_OPEN, frame, 0) == true then
      local k = CHD_KitAtc(frame)
      if k ~= nil then
        k[1], k[2] = k[1] + dx, k[2] + dy
        CHD_Cmd(CHD.NODE_POS, frame, 0, CHD.ATC_UNI, 0, k[1])
        CHD_Cmd(CHD.NODE_POS, frame, 0, CHD.ATC_UNI, 1, k[2])
      end
    end
  end
end

-- ---- focus ---------------------------------------------------------------------------------------------------------------
local function CHD_Active(layer)
  return CHD_Get(CHD.FOCUS_ACTIVE, layer) == true
end

local function CHD_Idx(layer)
  local v = CHD_Get(CHD.FOCUS_IDX, layer)
  if type(v) == "number" then
    return v
  end
  return 0
end

local function CHD_Num(layer)
  local v = CHD_Get(CHD.CREATE_NUM, layer)
  if type(v) == "number" then
    return v
  end
  return 1
end

local function CHD_Open(layer, idx)
  return CHD_Get(CHD.IS_OPEN, layer, idx or 0) == true
end

-- every Step (one correction, then 2 Steps to let the global positions follow): the AT / DF block (its _pos_scl01,
-- the centre of its line) onto CHD_ATDF.tx / ty field units from the keeper's spot _pos_formation01, the block scaled
-- to CHD_ATDF.scale of the field's scale. Everything measured in global units, so the dock's slide-in, a dock switch
-- or another mod moving / scaling the pitch or the block's layout only changes where it lands, not that it is under
-- the keeper. Only on the 11v11 pitch; otherwise the layer goes back to its retail transform.
local function CHD_Atdf()
  local A, st = CHD_ATDF, CHD.atdf
  if CHD_Get(CHD.IS_OPEN, A.layer, 0) ~= true then
    return
  end
  if not CHD_AtdfOn() or CHD_Get(CHD.IS_OPEN, A.frame, 0) ~= true then
    if st.x ~= 0 or st.y ~= 0 or st.s ~= 1 then
      st.x, st.y, st.s = 0, 0, 1
      CHD_AtdfSend()
    end
    return
  end
  if st.wait > 0 then
    st.wait = st.wait - 1
    return
  end
  local fbx, fby = CHD_G(A.frame, 0, CHD.POS_BASE)
  local ffx, ffy = CHD_G(A.frame, 0, A.field)
  local gx, gy = CHD_G(A.frame, 0, A.gk)
  local abx = CHD_G(A.layer, 0, CHD.POS_BASE)
  local asx, asy = CHD_G(A.layer, 0, A.scl)
  local _, any = CHD_G(A.layer, 0, A.num)
  if fbx == nil or ffx == nil or gx == nil or abx == nil or asx == nil or any == nil then
    return
  end
  local kfx, kfy = (ffx - fbx) / A.fx, (ffy - fby) / A.fy        -- global units per field unit
  local kax, kay = (asx - abx) / A.dx / st.s, (any - asy) / A.dy / st.s   -- per unscaled layer unit
  if math.abs(kfx) < 0.05 or math.abs(kfy) < 0.05 or math.abs(kax) < 0.05 or math.abs(kay) < 0.05 then
    return
  end
  local s = A.scale * kfy / kay
  if s < 0.2 or s > 1.5 then
    s = A.scale
  end
  local tx, ty = gx + A.tx * kfx, gy + A.ty * kfy
  local dx, dy = (tx - asx) / kax, (ty - asy) / kay
  if math.abs(s - st.s) < 0.005 and math.abs(dx) < 0.5 and math.abs(dy) < 0.5 then
    return
  end
  if math.abs(s - st.s) >= 0.005 then
    st.s = s                      -- the scale first (about the layer origin): the position is measured again after it
  else
    st.x, st.y = st.x + dx, st.y + dy
  end
  CHD_AtdfSend()
  st.wait = 2
  if st.n < 12 then
    st.n = st.n + 1
    CHD_Log(string.format("atdf -> pos %.1f, %.1f scale %.3f (block was %.1f, %.1f from target)", st.x, st.y, st.s,
      dx, dy))
  end
end

local function CHD_ConfShown()
  if not CHD_Open(CHD.CONF, 0) then
    return false
  end
  if type(IsVisibleTeamBuildTypeIcon) == "function" then
    local ok, v = pcall(IsVisibleTeamBuildTypeIcon, CHD.CONF)
    if ok and v == false then
      return false
    end
  end
  return true
end

-- the focus lands on (layer, idx): the retail marker, the engine's own index if the marker did not move it, then the
-- dock's OnChangeFocus (run by the engine's echo, else here) for its cursor / guide line / tactic info / balloon
local function CHD_SetFocus(layer, idx)
  CHD.busy, CHD.echo = true, false
  CHD_Cmd(CHD.FOCUS_MARK, layer, idx, true)
  if CHD_Idx(layer) ~= idx then
    CHD_Cmd(CHD.FOCUS_SET, layer, idx)
  end
  CHD.busy = false
  if not CHD.echo and type(OnChangeFocus) == "function" then
    pcall(OnChangeFocus, layer, idx)
  end
end

-- one instance of the tactics row to another, as the engine's own step inside a layer
local function CHD_TacStep(from, to)
  CHD_Cmd(3781155141 --[[CMND_PLAY_ANIME_TYPE]], CHD.TAC, from, 1286797620 --[[Active]], 2, 973515837 --[[button]])
  CHD_Cmd(3781155141 --[[CMND_PLAY_ANIME_TYPE]], CHD.TAC, from, 2734777837 --[[Focus]], 2, 973515837 --[[button]])
  CHD_Cmd(CHD.CURSOR_LOC, CHD.TAC, CHD.CURSOR, to, CHD_Num(CHD.TAC))
  CHD_SetFocus(CHD.TAC, to)
end

-- the focus mark and highlight off on an instance that no longer holds the focus (what the retail OnMouseMove does
-- to the item the pointer leaves, plus the out animations of OnFocusLayerShift)
local function CHD_Unfocus(layer, idx)
  CHD.busy = true
  CHD_Cmd(CHD.FOCUS_MARK, layer, idx, false)
  CHD.busy = false
  CHD_Cmd(3781155141 --[[CMND_PLAY_ANIME_TYPE]], layer, idx, 1286797620 --[[Active]], 2, 973515837 --[[button]])
  CHD_Cmd(3781155141 --[[CMND_PLAY_ANIME_TYPE]], layer, idx, 2734777837 --[[Focus]], 2, 973515837 --[[button]])
end

-- (from, fi) -> (to, ti) like a retail focus shift row: the dock's OnFocusLayerShift (plates, cursor trace, control
-- focus), the control focus, the cursor, the focus itself. `from` is unmarked: when it is the transient target of a
-- retail shift row this layout re-routes (FORMACIÓN DOWN -> CONF., kit LEFT -> CONF., team name RIGHT -> player
-- plate…), the engine had marked it and played its focus-in, and without this it kept its frame next to the real
-- focus (two items highlighted, in game 1.14.0). It is unmarked again for CHD_GHOST_STEPS Steps (CHD_Ghost): the
-- engine's own focus-in of the shift can land after this Step.
local CHD_GHOST_STEPS = 3
-- the team's identity fixed by the dock's opener (VRFW_TeamEditor.Foreign().lock_identity, a team page): the crest,
-- the team name, the kit and the home stadium button take no focus and no pointer. Read once per dock open (the dock
-- runs in a VM of its own)
CHD.LOCKED_LAYERS = {[1044086265] = true, [1922851874] = true, [3822105360] = true,   -- bar (crest), team name, kit
  [72691397] = true}   -- home_stadium_dock_button (Home Stadium's button in this panel: the opener's stadium, fixed)
function CHD.Locked()
  if CHD.lock == nil then
    local f = type(VRFW_TeamEditor) == "table" and type(VRFW_TeamEditor.Foreign) == "function"
      and VRFW_TeamEditor.Foreign() or nil
    CHD.lock = type(f) == "table" and f.tab == true and f.lock_identity == true
  end
  return CHD.lock
end

local function CHD_Go(from, fi, to, ti)
  if CHD.moves < 80 then
    CHD.moves = CHD.moves + 1
    CHD_Log("focus " .. tostring(from) .. "[" .. tostring(fi) .. "] -> " .. tostring(to) .. "[" .. tostring(ti) .. "]")
  end
  CHD.going = true
  if type(OnFocusLayerShift) == "function" then
    pcall(OnFocusLayerShift, from, fi, to, ti)
  end
  CHD.going = false
  CHD.focusAt = to
  CHD_Cmd(CHD.FOCUS_ENABLE, from, false)
  CHD_Cmd(CHD.FOCUS_ENABLE, to, true)
  CHD_Cmd(CHD.CURSOR_LOC, to, CHD.CURSOR, ti, CHD_Num(to))
  CHD_SetFocus(to, ti)
  if from ~= to then
    CHD_Unfocus(from, fi)
    CHD.ghost = {from, fi, CHD_GHOST_STEPS}
  end
end

-- every Step after a CHD_Go: the left item unmarked again while it does not hold the focus
local function CHD_Ghost()
  local g = CHD.ghost
  if g == nil then
    return
  end
  g[3] = g[3] - 1
  if g[3] <= 0 then
    CHD.ghost = nil
  end
  if not CHD_Active(g[1]) then
    CHD_Unfocus(g[1], g[2])
  else
    CHD.ghost = nil                -- the focus came back to it: leave it alone
  end
end

-- the nearest card of the pitch / bench from (layer, idx) in a retail direction (1 up, 2 down, 3 left, 4 right; the
-- retail CalcMoveFocusLayerIdx: positions measured, a cone, default 37°) -> card index or nil. Only a measure: the
-- layer's own instances are not candidates (count 0) and the focus does not move.
local function CHD_CardFrom(dir, layer, idx, cone)
  if type(CalcMoveFocusLayerIdx) ~= "function" then
    return nil
  end
  local ok, ci = pcall(CalcMoveFocusLayerIdx, layer, idx, dir, cone or 37, 0, CHD.POS_BASE, CHD.CARDS, nil, CHD.POS_BASE)
  if not ok or ci == nil or ci == -1 then
    return nil
  end
  return ci
end

-- the focus onto card `ci` of the pitch / bench (or the coach card: `to` = CHD.LEADER) the way the retail moves there
-- from the panel (control focus, cursor, mark, the dock's selected card, its guide line, no build balloon); `from` =
-- the layer the engine / this graft left
local function CHD_ToCard(from, fi, ci, to)
  to = to or CHD.CARDS
  -- the green cursor leaves `from` for the card, as the retail OnFocusLayerShift does (else it stays on the kit)
  for i = 0, CHD_Num(from) - 1 do
    CHD_Cmd(CHD.CURSOR_TRACE, from, i, CHD.CURSOR, false)
  end
  CHD_Cmd(CHD.CURSOR_TRACE, to, ci, CHD.CARD_CURSOR, true)
  CHD.focusAt = to
  CHD_Cmd(CHD.FOCUS_ENABLE, from, false)
  CHD_Cmd(CHD.FOCUS_ENABLE, to, true)
  CHD_Cmd(CHD.CURSOR_LOC, to, CHD.CURSOR, ci, CHD_Num(to))
  if type(SetIsTeamDockTop) == "function" then
    pcall(SetIsTeamDockTop, false)
  end
  if type(UpdateChangeFocusLayer) == "function" then
    -- from a card, the retail call that also takes the frame off the card left
    local fromCard = from == CHD.CARDS or from == CHD.LEADER
    pcall(UpdateChangeFocusLayer, to, fromCard and fi or ci, ci, fromCard and from or to)
  end
  if type(SetSelectCharaIdx) == "function" then
    pcall(SetSelectCharaIdx, ci)
  end
  local text = CHD_Lc(CHD.TEXT_GET, CHD.CARD_GUIDE)
  if type(text) == "string" then
    CHD_Cmd(CHD.SET_TEXT, CHD.GUIDE_LINE, CHD.GUIDE_NODE, text, 0)
  end
  CHD_Cmd(CHD.LAYER_VISIBLE, CHD.BALLOON, 0, false)
  if from ~= to then
    CHD_Unfocus(from, fi)
    CHD.ghost = {from, fi, CHD_GHOST_STEPS}
  end
end

-- header mode, FORMACIÓN DOWN: the panel has no row below FORMACIÓN | CONF. (the kit is in the header), so the next
-- row down is the nearest card below it (retail measure, as the tactics' UP to the coach card); none -> FORMACIÓN
-- keeps the focus. `at` / `ai` = where the engine's retail row put the focus (CONF. after the shift), unmarked
local function CHD_FormDown(at, ai)
  local ci = CHD_CardFrom(2, CHD.FORM, 0)
  if ci ~= nil then
    if CHD.moves < 80 then
      CHD.moves = CHD.moves + 1
      CHD_Log("focus " .. tostring(at) .. "[" .. tostring(ai) .. "] -> card " .. tostring(ci) .. " (FORMACIÓN DOWN)")
    end
    CHD_ToCard(at, ai, ci)
    if at ~= CHD.FORM then
      CHD_Unfocus(CHD.FORM, 0)
    end
  elseif at ~= CHD.FORM then
    CHD_Go(at, ai, CHD.FORM, 0)
  end
end

-- CONF. DE EQUIPO -> the pitch on the right: the retail EQUIPACIÓN move (OnChangeFocus, right) from the CONF. box
local function CHD_ConfToPitch(at, ai)
  at, ai = at or CHD.CONF, ai or 0
  local ci = CHD_CardFrom(4, CHD.CONF, 0)
  if ci ~= nil then
    CHD_ToCard(at, ai, ci)
    if at ~= CHD.CONF then
      CHD_Unfocus(CHD.CONF, 0)
    end
  elseif at ~= CHD.CONF then
    CHD_Go(at, ai, CHD.CONF, 0)   -- no card on the right: CONF. keeps the focus
  end
end

-- ---- another mod's picture button (BetterUI.AddDockButton) ---------------------------------------------------------------
CHD.SYN_UPPER, CHD.SYN_LOWER = 830633104, 1179455358   -- team00_17_synergy_attachment_button_flag / _pillar
CHD.slot = {layer = nil, x = 0, y = 0, wait = 0, placed = false, n = 0, extra = {}, live = 0, still = 0}
local CHD_SLOT_STILL = 8          -- Steps the button must stay on its place (the dock's slide-in over) before placing stops

-- the button shown: the first registered one whose layer is open (nil = none; never in the one-row tactics layout)
local function CHD_SlotLayer()
  if CHD_TacOn() then
    return nil
  end
  local bu = rawget(_ENV, "BetterUI")
  local list = type(bu) == "table" and rawget(bu, "DockButtons") or nil
  if type(list) ~= "table" then
    return nil
  end
  for _, e in ipairs(list) do
    if type(e) == "table" and type(e.layer) == "number" and CHD_Open(e.layer, 0) then
      return e.layer, e
    end
  end
  return nil
end

-- the button's help line in the dock's guide line
local function CHD_SlotHelp(spec)
  if type(spec) == "table" and type(spec.help) == "number" then
    local text = CHD_Lc(CHD.TEXT_GET, spec.help)
    if type(text) == "string" then
      CHD_Cmd(CHD.SET_TEXT, CHD.GUIDE_LINE, CHD.GUIDE_NODE, text, 0)
    end
  end
end

-- (from, fi) -> the button, with its help line
local function CHD_ToSlot(from, fi)
  local layer, spec = CHD_SlotLayer()
  if layer == nil or not CHD.slot.placed or (CHD.Locked() and CHD.LOCKED_LAYERS[layer]) then
    return false
  end
  CHD_Go(from, fi, layer, 0)
  CHD_SlotHelp(spec)
  return true
end

-- the spec's `extra` layers (root layers drawn over the button, e.g. its picture): their origin onto the button's,
-- measured in global units against the button (same layout units), hidden until there
local function CHD_SlotExtra(spec, bx, by, kbx, kby)
  local st = CHD.slot
  for _, ex in ipairs(type(spec) == "table" and type(spec.extra) == "table" and spec.extra or {}) do
    -- (an extra layer need not report itself open: the stadium picture frame never did, 1.22.13; it is placed as soon
    -- as its origin can be measured)
    if type(ex) == "number" and CHD_G(ex, 0, CHD.POS_BASE) ~= nil then
      local e = st.extra[ex]
      if e == nil then
        e = {x = 0, y = 0, wait = 0, placed = false}
        st.extra[ex] = e
        CHD_Cmd(CHD.LAYER_VISIBLE, ex, 0, false)
      end
      if e.wait > 0 then
        e.wait = e.wait - 1
      else
        local ex_x, ex_y = CHD_G(ex, 0, CHD.POS_BASE)
        if ex_x ~= nil then
          local dx, dy = (bx - ex_x) / kbx, (by - ex_y) / kby
          if math.abs(dx) < 0.5 and math.abs(dy) < 0.5 then
            if not e.placed then
              e.placed = true
              CHD_Cmd(CHD.LAYER_VISIBLE, ex, 0, true)
              CHD_Log("dock button " .. tostring(st.layer) .. ": layer " .. tostring(ex) .. " placed on it")
            end
          else
            e.x, e.y = e.x + dx, e.y + dy
            CHD_Cmd(CHD.LAYER_POS, ex, e.x, e.y, 0, 0)
            e.wait = 2
          end
        end
      end
    end
  end
end

-- (re)start placing the button: the events that move it (its layer / the field opening, the team switch, the dock back
-- from a child menu); placing runs until it has stayed on its place CHD_SLOT_STILL Steps
local function CHD_SlotArm()
  local st = CHD.slot
  st.live, st.still = 1, 0
  for _, e in pairs(st.extra or {}) do
    e.wait = 0
  end
  if type(CHD.IconsArm) == "function" then
    CHD.IconsArm()
  end
end
CHD.SlotArm = CHD_SlotArm

local function CHD_SlotPlace()
  local layer, spec = CHD_SlotLayer()
  local st = CHD.slot
  if layer == nil then
    return
  end
  if st.layer ~= layer then
    st.layer, st.x, st.y, st.wait, st.placed, st.n, st.extra, st.live, st.still = layer, 0, 0, 0, false, 0, {}, 1, 0
    CHD_Cmd(CHD.LAYER_VISIBLE, layer, 0, false)
  end
  -- the spec's own tick (its selector while it is open): every Step of the dock while the button's layer is open
  if type(spec.step) == "function" then
    local ok, err = pcall(spec.step, st.placed)
    if not ok and not st.stepErr then
      st.stepErr = true
      CHD_Log("dock button " .. tostring(layer) .. " step error " .. tostring(err))
    end
  end
  if st.live <= 0 then
    return                        -- placed and still: nothing until an event arms it again (CHD_SlotArm)
  end
  if st.wait > 0 then
    st.wait = st.wait - 1
    return
  end
  if st.placed and st.kb ~= nil then
    local bx0, by0 = CHD_G(layer, 0, CHD.POS_BASE)
    if bx0 ~= nil then
      CHD_SlotExtra(spec, bx0, by0, st.kb[1], st.kb[2])
    end
  end
  local ux, uy = CHD_G(CHD.SYN_UPPER, 0, CHD.POS_BASE)
  local lx, ly = CHD_G(CHD.SYN_LOWER, 0, CHD.POS_BASE)
  -- the spec's scale reference (a mesh node and its layout translation, default the synergy plate) and the point of
  -- its layer that goes on the slot's centre (layer units, default the origin), in the synergy buttons' column or on
  -- the panel's centre (column = "panel")
  local ms = type(spec.mesh) == "table" and spec.mesh or {node = CHD_SLOT.mesh, x = CHD_SLOT.mx, y = CHD_SLOT.my}
  local ce = type(spec.center) == "table" and spec.center or {x = 0, y = 0}
  local bx, by = CHD_G(layer, 0, CHD.POS_BASE)
  local mx, my = CHD_G(layer, 0, ms.node)
  if ux == nil or lx == nil or bx == nil or mx == nil then
    return
  end
  local k = (ly - uy) / CHD_SLOT.step                     -- global units per field unit (y, signed)
  local kbx, kby = (mx - bx) / ms.x, (my - by) / ms.y     -- per button layer unit
  if math.abs(k) < 0.05 or math.abs(kbx) < 0.05 or math.abs(kby) < 0.05 then
    return
  end
  st.kb = {kbx, kby}
  local col = spec.column == "panel" and CHD_SLOT.pdx or CHD_SLOT.dx
  local tx, ty = lx + col * math.abs(k), ly + CHD_SLOT.dy * k
  local dx, dy = (tx - (bx + ce.x * kbx)) / kbx, (ty - (by + ce.y * kby)) / kby
  if math.abs(dx) < 0.5 and math.abs(dy) < 0.5 then
    if not st.placed then
      st.placed = true
      CHD_Cmd(CHD.LAYER_VISIBLE, layer, 0, true)
      CHD_Log(string.format("dock button %s placed at %.1f, %.1f", tostring(layer), st.x, st.y))
    end
    st.still = st.still + 1
    if st.still >= CHD_SLOT_STILL then
      st.live = 0                 -- the slide-in is over: placing stops until the next event
    end
    return
  end
  st.still = 0
  st.x, st.y = st.x + dx, st.y + dy
  CHD_Cmd(CHD.LAYER_POS, layer, st.x, st.y, 0, 0)
  st.wait = 2
  if st.n < 8 then
    st.n = st.n + 1
    CHD_Log(string.format("dock button %s -> pos %.1f, %.1f (was %.1f, %.1f from its place)", tostring(layer), st.x, st.y,
      dx, dy))
  end
end

CHD.focusAt = nil                 -- the layer the dock's focus was last moved to (a shift, CHD_Go, CHD_ToCard): nil at open

-- a layer that is not where the focus is shows no focus: control focus off, the «Focus» animation out, no green
-- cursor, no focus mark. A new layer of the dock starts with its control focus ON (its own focus group), so the copied
-- boxes drew the focused look at open (owner 2026-10-19): the retail layers have it off until the dock moves there.
local function CHD_Unfocused(layer, idx)
  if CHD.focusAt == layer then
    return
  end
  CHD_Cmd(CHD.FOCUS_ENABLE, layer, false)
  CHD_Cmd(3781155141 --[[CMND_PLAY_ANIME_TYPE]], layer, idx, 2734777837 --[[Focus]], 2, 973515837 --[[button]])
  CHD_Cmd(CHD.CURSOR_TRACE, layer, idx, CHD.CURSOR, false)
  CHD_Cmd(CHD.FOCUS_MARK, layer, idx, false)
end

-- ---- the team editor's icon buttons (VRFW_TeamEditor spec.icons: vrfw_team_icon) -----------------------------------
-- One row of up to 3 picture buttons right above another mod's button, centred on the panel (CHD_ICONS); each opens a
-- dock list row's screen (VRFW lua\menu\soccer_team_dock_menu\130_foreign_team.lua). Placed like that button: from the
-- synergy buttons' measured places, hidden until placed, after the events that move the field (CHD_SlotArm). Focus:
-- CHD.PAD_MAP. With
-- spec.hide_list the list is off screen: a focus that lands on it (the dock's open, Back from a card, a retail row)
-- goes to the first icon (no icons: back where it came from). Not with EVT_CHD_TACTICS.
CHD.ICON = 330027688              -- vrfw_team_icon
CHD.ICON_MAX = 3                  -- vrfw_team_icon instances
-- each instance hangs from a joint of its own on the pitch frame, under the lower synergy button's _atc_synergy02
-- (BetterUI content/menus/team_icons_attach.toml: the frame's attach rows): the row is placed by writing those joints, so the
-- instance's pointer zone and cursor locator move with it (a layer moved with CMND_SET_LAYER_LOCAL_POS keeps its
-- zone and its cursor at the layout's place). {joint, x, y}: the joint and its translation in the layout (3 icons)
CHD.ICON_JOINTS = {
  {3112134118, -271.8, -292.6},   -- _atc_vrfw_icon01
  {544617564, -139.0, -292.6},    -- _atc_vrfw_icon02
  {1467024586, -6.2, -292.6},     -- _atc_vrfw_icon03
}

-- the pitch frame layer the icons hang from (the frame of this dock that has their joints), nil = none
function CHD.IconFrame()
  local I = CHD.Icons()
  if I.frame == nil then
    I.frame = false
    for _, frame in ipairs(CHD.FRAMES) do
      if CHD_G(frame, 0, CHD.ICON_JOINTS[1][1]) ~= nil then
        I.frame = frame
        break
      end
    end
    CHD_Log("icons hang from " .. (I.frame and ("frame " .. tostring(I.frame)) or "no frame joint: layer moves"))
  end
  return I.frame or nil
end

-- the icons of this open (read once per dock VM: VRFW_TeamEditor.Foreign())
function CHD.Icons()
  if CHD.icons == nil then
    local f = type(VRFW_TeamEditor) == "table" and type(VRFW_TeamEditor.Foreign) == "function"
      and VRFW_TeamEditor.Foreign() or nil
    local n = type(f) == "table" and type(f.icons) == "table" and #f.icons or 0
    CHD.icons = {n = CHD_TacOn() and 0 or math.min(n, CHD.ICON_MAX), hide = type(f) == "table" and f.hide_list == true,
      live = 1, still = 0, wait = 0, placed = false, spare = false, st = {}}
    if n > 0 or CHD.icons.hide then
      CHD_Log("icons: " .. CHD.icons.n .. ", list hidden " .. tostring(CHD.icons.hide))
    end
  end
  return CHD.icons
end

function CHD.IconsShown()
  local I = CHD.Icons()
  return I.n > 0 and I.placed
end

-- the help line of icon i: its list row's name and description (VRFW_TeamEditor.IconHelp)
function CHD.IconHelp(i)
  local f = type(VRFW_TeamEditor) == "table" and VRFW_TeamEditor.IconHelp or nil
  if type(f) ~= "function" then
    return
  end
  local ok, text = pcall(f, i)
  if ok and type(text) == "string" then
    CHD_Cmd(CHD.SET_TEXT, CHD.GUIDE_LINE, CHD.GUIDE_NODE, text, 0)
  end
end

-- (from, fi) -> icon i (clamped to the row), with its help line; false when the row is not shown
function CHD.ToIcon(from, fi, i)
  local I = CHD.Icons()
  if not CHD.IconsShown() then
    return false
  end
  i = math.max(0, math.min(i or 0, I.n - 1))
  if from == CHD.ICON and fi ~= i then
    CHD_Unfocus(CHD.ICON, fi)
  end
  CHD_Go(from, fi, CHD.ICON, i)
  CHD.IconHelp(i)
  return true
end

-- the focus landed on the hidden list: the first icon, else back to `from`
function CHD.OffList(at, ai, from, fi)
  if CHD.ToIcon(at, ai, 0) then
    return
  end
  if from ~= nil and from ~= at then
    CHD_Go(at, ai, from, fi or 0)
  end
end

-- every Step while armed: each icon instance's plate centre onto its place in the row (global units, as the button),
-- the unused instances hidden without pointer; once all stay put CHD_SLOT_STILL Steps placing stops until re-armed.
-- The first time the row is placed with the list hidden, the focus leaves the list for the first icon.
function CHD.IconsPlace()
  local I = CHD.Icons()
  if not I.spare and CHD_Open(CHD.ICON, 0) then
    I.spare = true
    for i = I.n, CHD_Num(CHD.ICON) - 1 do
      CHD_Cmd(CHD.LAYER_VISIBLE, CHD.ICON, i, false)
      CHD_Cmd(CHD.ZONE, CHD.ICON, i, false)
    end
  end
  if I.n == 0 or I.live <= 0 then
    return
  end
  local ux, uy = CHD_G(CHD.SYN_UPPER, 0, CHD.POS_BASE)
  local lx, ly = CHD_G(CHD.SYN_LOWER, 0, CHD.POS_BASE)
  if ux == nil or lx == nil then
    return
  end
  local k = (ly - uy) / CHD_SLOT.step                     -- global units per field unit (y, signed)
  if math.abs(k) < 0.05 then
    return
  end
  local all = true
  for i = 0, I.n - 1 do
    local s = I.st[i]
    if s == nil and CHD_Open(CHD.ICON, i) then
      local j = CHD.ICON_JOINTS[i + 1]
      s = {x = j and j[2] or 0, y = j and j[3] or 0, joint = j and CHD.IconFrame() and j[1] or nil, wait = 1,
        placed = false}
      I.st[i] = s
      CHD_Cmd(CHD.LAYER_VISIBLE, CHD.ICON, i, false)
      CHD_Cmd(CHD.LAYER_SCALE, CHD.ICON, CHD_ICONS.scale, CHD_ICONS.scale, 1, i)
    end
    if s == nil then
      all = false
    elseif s.wait > 0 then
      s.wait = s.wait - 1
      all = false
    else
      local bx, by = CHD_G(CHD.ICON, i, CHD.POS_BASE)
      local mx, my = CHD_G(CHD.ICON, i, CHD_SLOT.mesh)
      local kbx = bx ~= nil and mx ~= nil and (mx - bx) / CHD_SLOT.mx or 0   -- global units per layer unit (scaled)
      local kby = bx ~= nil and mx ~= nil and (my - by) / CHD_SLOT.my or 0
      if math.abs(kbx) < 0.05 or math.abs(kby) < 0.05 then
        all = false
      else
        local tx = lx + (CHD_ICONS.pdx + (i - (I.n - 1) / 2) * CHD_ICONS.step) * math.abs(k)
        local ty = ly + CHD_ICONS.dy * k
        local dx, dy = (tx - bx) / kbx * CHD_ICONS.scale, (ty - by) / kby * CHD_ICONS.scale
        if math.abs(dx) < 0.5 and math.abs(dy) < 0.5 then
          if not s.placed then
            s.placed = true
            CHD_Cmd(CHD.LAYER_VISIBLE, CHD.ICON, i, true)
          end
        elseif s.joint ~= nil then
          -- the joint moved (frame layout units: |k| global units per unit in x, k in y)
          s.x, s.y, s.wait = s.x + (tx - bx) / math.abs(k), s.y + (ty - by) / k, 2
          CHD_Cmd(CHD.NODE_POS, CHD.IconFrame(), 0, s.joint, 0, s.x)
          CHD_Cmd(CHD.NODE_POS, CHD.IconFrame(), 0, s.joint, 1, s.y)
          all = false
        else
          s.x, s.y, s.wait = s.x + dx, s.y + dy, 2
          CHD_Cmd(CHD.LAYER_POS, CHD.ICON, s.x, s.y, 0, i)
          all = false
        end
      end
    end
  end
  if not all then
    I.still = 0
    return
  end
  I.still = I.still + 1
  if I.still >= CHD_SLOT_STILL then
    I.live = 0
  end
  if not I.placed then
    I.placed = true
    CHD_Log(string.format("icons placed (%d), list hidden %s", I.n, tostring(I.hide)))
    if I.hide and CHD_Active(CHD.LIST) then
      CHD.ToIcon(CHD.LIST, CHD_Idx(CHD.LIST), 0)
    end
  end
end

-- the events that move the field: place the icons again
function CHD.IconsArm()
  local I = CHD.icons
  if I ~= nil then
    I.live, I.still = 1, 0
    for _, s in pairs(I.st) do
      s.wait = 0
    end
  end
end

-- every Step: the header's pointer zones (engine zones = layout rectangles, docs/game/ui/ui-redesign.md «pointer zones
-- do not follow node writes») matched to what is drawn, so hovering an item focuses that item:
--   crest     its zone (_touch_emblem01 of BetterUI's team01_04_evt_bui layout) is on the header-mode crest: on only
--             while the header relayout is applied (header mode); off otherwise (the crest is drawn at its retail place
--             then and the zone would lie on the retail team name plate)
--   team name its zone runs 456 px from the plate's left (the plate is narrower): off while the pointer is right of the
--             drawn plate (over the kit, the gap, the player plate's left end)
--   kit       its zone is the retail 130 px square around the drawn 100 px kit: off while the pointer is outside the
--             drawn kit (it ran over the team name's and the player plate's ends)
-- A zone that is off only stops hover / click inside its own rectangle (retail 855005857 (layer, idx, bool), the call
-- the dock makes for every zone during a dock move); never while the layer's group is suspended (child menu, dock
-- move): the retail owns the zones then. Pointer = screen px, y down; global positions compared with (x, -y) as the
-- retail players_universe_menu does. Every switch is logged (first 24).
function CHD.Zone(layer, off, why)
  if (CHD.zoneOff[layer] == true) == off then
    return
  end
  CHD.zoneOff[layer] = off
  CHD_Cmd(CHD.ZONE, layer, 0, not off)
  if CHD.zoneLogs < 24 then
    CHD.zoneLogs = CHD.zoneLogs + 1
    CHD_Log("pointer zone of " .. tostring(layer) .. (off and " off" or " on") .. " (" .. why .. ")")
  end
end

function CHD.HeaderZones()
  if CHD.Locked() then
    for layer in pairs(CHD.LOCKED_LAYERS) do
      if CHD_Open(layer, 0) and CHD_Get(CHD.LAYER_ACTIVE, layer) ~= false then
        CHD.Zone(layer, true, "the team's identity is fixed")
      end
    end
    return
  end
  CHD.zoneTick = (CHD.zoneTick or 0) + 1
  if CHD.zoneTick >= 30 then       -- a dock move / child menu switches every zone on again behind this cache
    CHD.zoneTick = 0
    for layer, off in pairs(CHD.zoneOff) do
      if off and CHD_Open(layer, 0) and CHD_Get(CHD.LAYER_ACTIVE, layer) ~= false then
        CHD_Cmd(CHD.ZONE, layer, 0, false)
      end
    end
  end
  if CHD_Open(CHD.BAR, 0) and CHD_Get(CHD.LAYER_ACTIVE, CHD.BAR) ~= false then
    local hdr = CHD_PanelOn() and CHD.hdr == "header"
    CHD.Zone(CHD.BAR, not hdr, hdr and "crest drawn on its zone" or "crest not drawn on its zone")
  end
  if not CHD_PanelOn() or CHD.hdr ~= "header" then
    return
  end
  local ok, x, y = CHD_Cmd(CHD.POINTER)
  if not ok or type(x) ~= "number" or type(y) ~= "number" then
    return
  end
  local k = CHD.kitc
  local onKit = k ~= nil and math.abs(x - k[1]) <= k[3] and math.abs(-y - k[2]) <= k[4]
  if CHD_Open(CHD.NAME, 0) and CHD_Get(CHD.LAYER_ACTIVE, CHD.NAME) ~= false then
    local right = CHD.nameR ~= nil and x > CHD.nameR
    CHD.Zone(CHD.NAME, onKit or right, string.format("pointer %.0f,%.0f, plate right edge %s", x, y,
      CHD.nameR ~= nil and string.format("%.0f", CHD.nameR) or "?"))
  end
  if k ~= nil and CHD_Open(CHD.UNI, 0) and CHD_Get(CHD.LAYER_ACTIVE, CHD.UNI) ~= false then
    CHD.Zone(CHD.UNI, not onKit, string.format("pointer %.0f,%.0f, kit %.0f,%.0f +-%.0f,%.0f", x, y, k[1], k[2], k[3],
      k[4]))
  end
end

-- every Step (header mode): one log line each time the focus moves to / within / off the header items, with the pointer
-- (to tell a hover from a key move in the log: the pointer stays put on a key move)
CHD.HDR_ITEMS = {{"crest", CHD.BAR}, {"team name", CHD.NAME}, {"kit", CHD.UNI}, {"player plate", CHD.DECK}}
function CHD.HeaderFocusLog()
  if CHD.hdr ~= "header" or CHD.hfocusLogs >= 60 then
    return
  end
  local cur = "other"
  for _, it in ipairs(CHD.HDR_ITEMS) do
    if CHD_Open(it[2], 0) and CHD_Active(it[2]) then
      cur = it[1]
    end
  end
  if cur == CHD.hfocus then
    return
  end
  local prev = CHD.hfocus
  CHD.hfocus = cur
  if prev == nil and cur == "other" then
    return
  end
  CHD.hfocusLogs = CHD.hfocusLogs + 1
  local ok, x, y = CHD_Cmd(CHD.POINTER)
  CHD_Lc(1563215927 --[[CMND_EVT_LOG_DEBUG]], "EVT dock_panel " .. string.format("header focus %s -> %s (pointer %s)", tostring(prev), cur,
    (ok and type(x) == "number" and type(y) == "number") and string.format("%.0f,%.0f", x, y) or "?"))
end

-- every Step (2026-10-13, owner: the pointer on CONF. DE EQUIPO lit FORMACIÓN): the same rule for the FORMACIÓN | CONF.
-- row. Their engine zones are their retail rectangles (FORMACIÓN 398 px, centred on the retail text; CONF. 194 x 130,
-- centred on the drawn box by the generator), so each runs over the other's drawn box. While the pointer is on one
-- drawn box, the other one's zone is switched off; anywhere else both are on (retail). Drawn box = the box mesh (first
-- row of CHD_FORM / CHD_CONF: top-left + size) measured in global units, the scale from its _pos_atc_free01 row.
CHD.FREE_NODE = 4293674698        -- _pos_atc_free01
CHD.boxOff = {}
CHD.boxLogs = 0
function CHD.Drawn(layer, rows)
  local base, ref = rows[1], nil
  for _, r in ipairs(rows) do
    if r[1] == CHD.FREE_NODE then
      ref = r
    end
  end
  if ref == nil or ref[2] == base[2] or ref[3] == base[3] or not CHD_Open(layer, 0) then
    return nil
  end
  local gx, gy = CHD_G(layer, 0, base[1])
  local fx, fy = CHD_G(layer, 0, ref[1])
  if gx == nil or fx == nil then
    return nil
  end
  local kx, ky = (fx - gx) / (ref[2] - base[2]), (fy - gy) / (ref[3] - base[3])
  if math.abs(kx) < 0.05 or math.abs(ky) < 0.05 then
    return nil
  end
  local x1, y1 = gx + base[4] * kx, gy - base[5] * ky
  return {math.min(gx, x1), math.max(gx, x1), math.min(gy, y1), math.max(gy, y1)}
end

-- the pointer against the two drawn boxes: inForm, inConf (false, false when unmeasurable or the pointer is unknown)
function CHD.PointerBoxes()
  local ok, x, y = CHD_Cmd(CHD.POINTER)
  if not ok or type(x) ~= "number" or type(y) ~= "number" then
    return nil
  end
  local f, c = CHD.Drawn(CHD.FORM, CHD_FORM), CHD.Drawn(CHD.CONF, CHD_CONF)
  if f == nil or c == nil then
    return nil
  end
  local function inside(b)
    return x >= b[1] and x <= b[2] and -y >= b[3] and -y <= b[4]
  end
  return inside(f), inside(c), x, y
end

-- each zone is on only while the pointer is on its own drawn box (2026-10-15, owner: the pointer on CONF. DE EQUIPO
-- still lit FORMACIÓN): the retail rectangles overlap each other and the gap between the boxes
function CHD.BoxGuard()
  if not CHD_PanelOn() or CHD_Get(CHD.LAYER_ACTIVE, CHD.FORM) == false then
    return                        -- a child menu is up / the dock is moving: the retail owns the zones
  end
  local off = {}
  if CHD_ConfShown() then
    local inF, inC, x, y = CHD.PointerBoxes()
    if inF ~= nil then
      off[CHD.FORM] = not inF
      off[CHD.CONF] = not inC
      CHD.boxPointer = {x, y}
    end
  end
  for _, layer in ipairs({CHD.FORM, CHD.CONF}) do
    local o, was = off[layer] == true, CHD.boxOff[layer] == true
    if o or was then              -- never touches a zone this guard did not switch off
      if was ~= o and CHD.boxLogs < 40 then
        CHD.boxLogs = CHD.boxLogs + 1
        local p = CHD.boxPointer
        CHD_Lc(1563215927 --[[CMND_EVT_LOG_DEBUG]], "EVT dock_panel pointer box guard: zone of " .. tostring(layer) .. (o and " off" or " on") .. (p and string.format(
          " (pointer %.0f,%.0f)", p[1], p[2]) or ""))
      end
      CHD.boxOff[layer] = o
      CHD_Cmd(CHD.ZONE, layer, 0, not o)
    end
  end
end

-- true while the pointer is on the drawn box of FORMACIÓN / CONF. DE EQUIPO (layer)
function CHD.PointerOnBox(layer)
  local inF, inC = CHD.PointerBoxes()
  if layer == CHD.FORM then
    return inF == true
  end
  return inC == true
end

-- ---- wrappers --------------------------------------------------------------------------------------------------------------
local function CHD_After(name, after)
  local prev = rawget(_ENV, name)
  if type(prev) ~= "function" then
    return
  end
  rawset(_ENV, name, function(...)
    local r = CHD_Pack(prev(...))
    local ok, err = pcall(after, ...)
    if not ok then
      CHD_Log("error " .. name .. " " .. tostring(err))
    end
    return table.unpack(r, 1, r.n)
  end)
end

CHD_After("OnSetupLayer", function(a1, a2)
  CHD_Apply(a1, a2)
end)
CHD_After("OnOpenLayer", function(a1, a2)
  CHD_Apply(a1, a2)
  if a1 ~= nil and a1 == CHD_SlotLayer() then
    CHD_Unfocused(a1, a2 or 0)    -- the dock button opens without the focused look (unless the focus is on it)
  end
  if a1 == CHD.ICON then
    CHD_Unfocused(a1, a2 or 0)    -- the icon buttons open without the focused look (unless the focus is on them)
    local I, s = CHD.Icons(), CHD.Icons().st[a2 or 0]
    if (a2 or 0) >= I.n or s == nil or not s.placed then
      CHD_Cmd(CHD.LAYER_VISIBLE, a1, a2 or 0, false)   -- hidden until placed; an unused one stays hidden
    end
    if (a2 or 0) >= I.n then
      CHD_Cmd(CHD.ZONE, a1, a2 or 0, false)
    end
  end
  if a1 == CHD.slot.layer or a1 == CHD.ICON or a1 == CHD.FRAMES[1] or a1 == CHD.FRAMES[2] or a1 == CHD.SYN_LOWER then
    CHD.SlotArm()                 -- the button / icons / field (11v11 / 5v5) opening: the dock slides in, place again
  end
end)
-- the team switch and the dock back from a child menu move the field: place the button again
CHD_After("UpdateTeamDockNo", function()
  CHD.SlotArm()
end)
CHD_After("ResumeTeamDock", function()
  CHD.SlotArm()
end)
-- the retail sets the tactic's name and plate per instance (setup, open, every refresh)
CHD_After("SetupTacticsLayer", function(a1, a2)
  if a1 == CHD.CMD then
    CHD_Apply(CHD.CMD, a2)
  end
end)
-- the INCLUDE shows the team config's name again on every refresh
CHD_After("UpdateTeamBuildTypeInfo", function(a1, a2, a3)
  if CHD_PanelOn() and (a3 == nil or a3 == CHD.CONF) then
    CHD_HideConfText()
  end
end)
-- the retail shows both kit sprites on every refresh: the drop shadow off again after it (in header mode it also has
-- size 0 in CHD_UNI: after a dock switch the kit icon finishes loading after this and shows the shadow again)
CHD_After("SetupUniformIcom", function(a1, a2)
  if CHD_PanelOn() and CHD.hdr == "header" and (a1 == nil or a1 == CHD.UNI) then
    CHD_Cmd(CHD.MESH_VIS, CHD.UNI, CHD.KIT_SHADOW, false, a2 or 0)
  end
end)
-- the retail writes the team level / name on every refresh of the bar: the «Nv.» sprite again after it
CHD_After("SetupTeamDockTeamNameBar", function()
  CHD_Apply(CHD.BAR, 0)
end)

-- ---- the pad map -----------------------------------------------------------------------------------------------------------
-- element -> direction -> targets, the first one available wins. A `nearest` entry measures: the target closest to the
-- card on that axis. Card to card, list up / down and Partido <-> Pachanga stay outside: retail and Friendlies.
CHD.PAD_DIRS = {"up", "down", "left", "right"}   -- the retail direction numbers 1..4
CHD.PAD_MAP = {
  list = {right = {"crest_from_cell", "coach", "tactic_top", "card"}},
  coach = {left = {"list"}, right = {"flag", "pillar", "card"}, up = {"crest", "name"},
    down = {"tactic_top", "icon_first", "slot", "formation"}},
  flag = {left = {"coach", "list"}, right = {"card"}, up = {"name", "crest"},
    down = {"pillar", "tactic_top", "icon_first", "slot", "formation"}},
  pillar = {left = {"coach", "list"}, right = {"card"}, up = {"flag", "name", "crest"},
    down = {"tactic_top", "icon_first", "slot", "formation"}},
  tactic = {left = {"tactic_left", "list"}, right = {"tactic_right", "card"},
    up = {"tactic_above", "coach", "flag"}, down = {"tactic_below", "icon_first", "slot", "formation"}},
  icon = {left = {"icon_before", "list"}, right = {"icon_after", "card"}, up = {"tactic_bottom", "coach"},
    down = {"slot", "formation"}},
  slot = {left = {"list"}, right = {"card"}, up = {"icon_first", "tactic_bottom", "coach"}, down = {"formation"}},
  formation = {left = {"list"}, right = {"team_settings", "card"},
    up = {"slot", "icon_first", "tactic_bottom", "coach"}, down = {"kit_panel", "card"}},
  team_settings = {left = {"formation"}, right = {"card"},
    up = {"slot", "icon_last", "tactic_bottom", "coach"}, down = {"kit_panel"}},
