  crest = {left = {"list"}, right = {"name"}, down = {"coach", "tactic_top", "formation"}},
  name = {left = {"crest", "list"}, right = {"kit", "player_plate"}, down = {"card", "flag", "coach"}},
  kit = {left = {"name", "crest"}, right = {"player_plate"}, down = {"card", "flag", "coach"}},
  player_plate = {left = {"kit", "name"}, down = {"card"}},
  card = {
    left = {nearest = "y", among = {"flag", "pillar", "coach", "tactic_top", "tactic_middle", "tactic_bottom",
      "icon_first", "icon_last", "slot", "team_settings", "formation", "kit_panel"}},
    up = {nearest = "x", among = {"crest", "name", "kit", "player_plate"}},
  },
}

-- the direction rows: betterui_dock_pad_* (dock_pad_rows.toml), betterui_dock_button_* (a mod's picture button),
-- vrfw_team_icon_* (team_icons.toml)
CHD.PAD_FN = {
  [2909329368] = 1, [623165486] = 2, [1136441213] = 3, [3643689647] = 4,
  [2122449173] = 1, [885050662] = 2, [1381546613] = 3, [3622053520] = 4,
  [3213729062] = 1, [957527670] = 2, [1602928933] = 3, [3162678559] = 4,
}
-- OnChangeFocus arguments of the cards' and the coach card's retail direction rows
CHD.PAD_CARD_ARG = {[3483715641] = 1, [49409691] = 2, [1684642248] = 3, [1644353666] = 4}
-- the layers that are one element
CHD.PAD_ELEMENT = {[CHD.TAC] = "tactic", [CHD.FORM] = "formation", [CHD.CONF] = "team_settings", [CHD.BAR] = "crest",
  [CHD.NAME] = "name", [CHD.DECK] = "player_plate", [CHD.SYN_UPPER] = "flag", [CHD.SYN_LOWER] = "pillar",
  [CHD.ICON] = "icon", [CHD.LIST] = "list", [CHD.LEADER] = "coach", [CHD.CARDS] = "card"}

function CHD.PadElement(layer)
  if layer == CHD.UNI then
    return CHD.hdr == "header" and "kit" or "kit_panel"
  end
  if layer == CHD_SlotLayer() then
    return "slot"
  end
  return CHD.PAD_ELEMENT[layer]
end

-- an instance that can take the focus now
function CHD.PadShown(layer, idx)
  if not CHD_Open(layer, idx) or CHD_Get(CHD.IS_VISIBLE, layer, idx) == false then
    return false
  end
  return not (CHD.Locked() and CHD.LOCKED_LAYERS[layer])
end

-- the layer drawn for this card instance: the card, else its blank slot (empty slots, the planner's ghosts)
function CHD.PadCardLayer(layer, idx)
  if layer ~= CHD.CARDS and layer ~= CHD.LEADER then
    return layer
  end
  if CHD.PadShown(layer, idx) or type(GetBlankCardName) ~= "function" then
    return layer
  end
  return GetBlankCardName(layer)
end

-- the list row beside row i in that direction on its own line (Friendlies' two cells), measured; nil = none
function CHD.PadRowBeside(i, dir)
  if type(CalcMoveFocusLayerIdx) ~= "function" then
    return nil
  end
  local ok, j = pcall(CalcMoveFocusLayerIdx, CHD.LIST, i, dir, 5, CHD_Num(CHD.LIST), CHD.POS_BASE)
  if ok and type(j) == "number" and j ~= -1 then
    return j
  end
  return nil
end

function CHD.PadOne(layer, idx)
  if CHD.PadShown(layer, idx) then
    return layer, idx
  end
  return nil
end

-- a tactic row of the column: instance 2 is the top one, 0 the bottom one
function CHD.PadTactic(idx)
  if CHD_TacOn() or idx < 0 or idx > 2 then
    return nil
  end
  return CHD.PadOne(CHD.TAC, idx)
end

-- a box of the old one-row tactics layout (EVT_CHD_TACTICS): instance 2 is the left one
function CHD.PadTacticBox(idx)
  if not CHD_TacOn() or idx < 0 or idx > 2 then
    return nil
  end
  return CHD.PadOne(CHD.TAC, idx)
end

function CHD.PadIcon(idx)
  if not CHD.IconsShown() or idx < 0 or idx >= CHD.Icons().n then
    return nil
  end
  return CHD.ICON, idx
end

-- target name -> function (from layer, from instance, direction) returning layer, instance; nil = not available
CHD.PAD_TARGET = {
  list = function(from)
    if CHD.Icons().hide then
      return nil
    end
    -- from the crest: the cell on its line, when the list has cells
    if from == CHD.BAR then
      for i = CHD_Num(CHD.LIST) - 1, 0, -1 do
        if CHD.PadShown(CHD.LIST, i) and CHD.PadRowBeside(i, 3) ~= nil then
          return CHD.LIST, i
        end
      end
    end
    return CHD.PadOne(CHD.LIST, CHD.listRow or CHD_Idx(CHD.LIST))
  end,
  crest_from_cell = function(from, fi)
    if from == CHD.LIST and CHD.PadRowBeside(fi, 3) ~= nil then
      return CHD.PadOne(CHD.BAR, 0)
    end
    return nil
  end,
  coach = function()
    local drawn = CHD.PadCardLayer(CHD.LEADER, 0)
    if drawn ~= 0 and CHD.PadShown(drawn, 0) then
      return CHD.LEADER, 0
    end
    return nil
  end,
  flag = function() return CHD.PadOne(CHD.SYN_UPPER, 0) end,
  pillar = function() return CHD.PadOne(CHD.SYN_LOWER, 0) end,
  tactic_top = function() return CHD.PadTactic(2) end,
  tactic_middle = function() return CHD.PadTactic(1) end,
  tactic_bottom = function() return CHD.PadTactic(0) end,
  tactic_above = function(_, fi) return CHD.PadTactic(fi + 1) end,
  tactic_below = function(_, fi) return CHD.PadTactic(fi - 1) end,
  tactic_left = function(_, fi) return CHD.PadTacticBox(fi + 1) end,
  tactic_right = function(_, fi) return CHD.PadTacticBox(fi - 1) end,
  slot = function()
    local layer = CHD_SlotLayer()
    if layer ~= nil and CHD.slot.placed then
      return CHD.PadOne(layer, 0)
    end
    return nil
  end,
  icon_first = function() return CHD.PadIcon(0) end,
  icon_last = function() return CHD.PadIcon(CHD.Icons().n - 1) end,
  icon_before = function(_, fi) return CHD.PadIcon(fi - 1) end,
  icon_after = function(_, fi) return CHD.PadIcon(fi + 1) end,
  formation = function() return CHD.PadOne(CHD.FORM, 0) end,
  team_settings = function()
    if CHD_ConfShown() then
      return CHD.PadOne(CHD.CONF, 0)
    end
    return nil
  end,
  kit = function()
    if CHD.hdr == "header" then
      return CHD.PadOne(CHD.UNI, 0)
    end
    return nil
  end,
  kit_panel = function()
    if CHD.hdr ~= "header" then
      return CHD.PadOne(CHD.UNI, 0)
    end
    return nil
  end,
  crest = function() return CHD.PadOne(CHD.BAR, 0) end,
  name = function() return CHD.PadOne(CHD.NAME, 0) end,
  player_plate = function() return CHD.PadOne(CHD.DECK, 0) end,
  card = function(from, fi, dir)
    -- a wider cone for what has no card straight ahead (the header row over the pitch)
    local ci = CHD_CardFrom(dir, from, fi) or CHD_CardFrom(dir, from, fi, 60) or CHD_CardFrom(dir, from, fi, 80)
    if ci ~= nil then
      return CHD.CARDS, ci
    end
    return nil
  end,
}

-- the available target of `among` closest to the card: on axis y the same height first, a closer column on a tie (and
-- only what is on its left); on axis x the same column
function CHD.PadNearest(from, fi, spec)
  local fx, fy = CHD_G(CHD.PadCardLayer(from, fi), fi, CHD.POS_BASE)
  if fx == nil then
    return nil
  end
  local bestLayer, bestIdx, bestScore = nil, nil, nil
  for _, name in ipairs(spec.among) do
    local layer, idx = CHD.PAD_TARGET[name](from, fi)
    local x, y = nil, nil
    if layer ~= nil then
      x, y = CHD_G(CHD.PadCardLayer(layer, idx), idx, CHD.POS_BASE)
    end
    if x ~= nil then
      local score = nil
      if spec.nearest == "x" then
        score = math.abs(x - fx)
      elseif x < fx then
        score = math.abs(y - fy) + (fx - x) / 4
      end
      if score ~= nil and (bestScore == nil or score < bestScore) then
        bestLayer, bestIdx, bestScore = layer, idx, score
      end
    end
  end
  return bestLayer, bestIdx
end

-- moves the focus with the one function that fits the target's kind
function CHD.PadMove(from, fi, to, ti)
  if to == CHD.CARDS or to == CHD.LEADER then
    CHD_ToCard(from, fi, ti, to)
  elseif to == CHD.TAC and from == CHD.TAC then
    CHD_TacStep(fi, ti)
  elseif to == CHD.ICON then
    CHD.ToIcon(from, fi, ti)
  elseif to == CHD_SlotLayer() then
    CHD_ToSlot(from, fi)
  else
    CHD_Go(from, fi, to, ti)
    if to == CHD.LIST then
      -- as the retail BackToTeamDockListItem: the row's frame
      CHD_Cmd(3781155141 --[[CMND_PLAY_ANIME_TYPE]], to, ti, 2734777837 --[[Focus]], 0, 973515837 --[[button]])
    end
  end
end

-- one pad step from (layer, idx); true = the focus moved
function CHD.Pad(layer, idx, dir)
  local element = CHD.PadElement(layer)
  local entry = element and CHD.PAD_MAP[element]
  local targets = entry and entry[CHD.PAD_DIRS[dir]]
  if targets == nil then
    return false
  end
  local to, ti = nil, nil
  if targets.nearest ~= nil then
    to, ti = CHD.PadNearest(layer, idx, targets)
  else
    for _, name in ipairs(targets) do
      to, ti = CHD.PAD_TARGET[name](layer, idx, dir)
      if to ~= nil then
        break
      end
    end
  end
  if to == nil then
    return false
  end
  CHD.PadMove(layer, idx, to, ti)
  CHD_Lc(CHD.SOUND, CHD.SE_MOVE)
  return true
end

-- a card has a card to go to in that direction: both retail measures of OnChangeFocus / OnChangeFocusCommon
function CHD.PadCardAhead(idx, dir)
  if type(CalcMoveFocusLayerIdx) ~= "function" or type(CalcMoveFocusLayerByCircleCollision) ~= "function" then
    return true
  end
  local ok, near = pcall(CalcMoveFocusLayerIdx, CHD.CARDS, idx, dir, 37, CHD_Num(CHD.CARDS), CHD.POS_BASE, nil, nil,
    CHD.POS_BASE)
  if not ok or near == -1 then
    return not ok
  end
  local okCircle, hit = pcall(CalcMoveFocusLayerByCircleCollision, CHD.CARDS, idx, dir, nil, CHD.POS_BASE, CHD.LEADER)
  return not okCircle or hit ~= -1
end

-- the retail direction rows that reach OnChangeFocus: a list row's RIGHT and the coach / card keys. true = answered here
function CHD.PadFromChange(layer, arg)
  local dir = nil
  if layer == CHD.LEADER or layer == CHD.CARDS then
    dir = CHD.PAD_CARD_ARG[arg]
  elseif layer == CHD.LIST and arg == CHD.ARG_RIGHT then
    dir = 4
  end
  if dir == nil or not CHD_Active(layer) then
    return false
  end
  local idx = CHD_Idx(layer)
  if layer == CHD.LIST and CHD.PadRowBeside(idx, 4) ~= nil then
    return false                  -- Partido -> Pachanga: Friendlies' own step
  end
  if layer == CHD.CARDS then
    if type(IsChangeMemberMode) == "function" and IsChangeMemberMode() == true then
      return false
    end
    if CHD.PadCardAhead(idx, dir) then
      return false
    end
  end
  CHD.Pad(layer, idx, dir)
  return true
end

-- a direction row of CMD_FUNCTION: the layer holding the control focus takes the step
function CHD.PadFromRow(dir)
  local slot = CHD_SlotLayer()
  if slot ~= nil and CHD_Active(slot) then
    CHD.Pad(slot, 0, dir)
    return
  end
  if CHD_Active(CHD.UNI) then
    CHD.Pad(CHD.UNI, 0, dir)
    return
  end
  for layer in pairs(CHD.PAD_ELEMENT) do
    if layer ~= CHD.LIST and layer ~= CHD.CARDS and layer ~= CHD.LEADER and CHD_Active(layer) then
      CHD.Pad(layer, CHD_Idx(layer), dir)
      return
    end
  end
end

local chd_prev_change = rawget(_ENV, "OnChangeFocus")
if type(chd_prev_change) == "function" then
  rawset(_ENV, "OnChangeFocus", function(a1, a2, ...)
    if a1 == CHD.ICON and not CHD.busy then
      local r = CHD_Pack(chd_prev_change(a1, a2, ...))
      CHD.IconHelp(CHD_Idx(CHD.ICON))
      return table.unpack(r, 1, r.n)
    end
    if CHD.busy then
      CHD.echo = true
    elseif CHD.PadFromChange(a1, a2) then
      return
    end
    local r = CHD_Pack(chd_prev_change(a1, a2, ...))
    if a1 == CHD.LIST and CHD_Active(CHD.LIST) then
      CHD.listRow = CHD_Idx(CHD.LIST)   -- the row LEFT comes back to
    end
    return table.unpack(r, 1, r.n)
  end)
end

local chd_prev_fn = rawget(_ENV, "OnFunction")
if type(chd_prev_fn) == "function" then
  rawset(_ENV, "OnFunction", function(a1, ...)
    local dir = CHD.PAD_FN[a1]
    if dir ~= nil then
      CHD.PadFromRow(dir)
      return
    end
    local r = CHD_Pack(chd_prev_fn(a1, ...))
    -- Back from a card gives the retail focus to the list (BackToTeamDockListItem): with the list hidden, the first icon
    if CHD.Icons().hide and CHD_Active(CHD.LIST) then
      CHD.OffList(CHD.LIST, CHD_Idx(CHD.LIST))
    end
    return table.unpack(r, 1, r.n)
  end)
end

-- ---- header mode: decided once the bar's layers are open, then the placed header is measured ----------------------
local function CHD_SetMode(mode, why)
  CHD.hdr = mode
  CHD_Log("header " .. mode .. " (" .. why .. ")")
  for _, L in ipairs({CHD.BAR, CHD.NAME, CHD.UNI}) do
    if CHD_Open(L, 0) then
      CHD_ApplyHeader(L, mode)
    end
  end
  for _, frame in ipairs(CHD.FRAMES) do
    if CHD_Open(frame, 0) then
      local k = mode == "header" and CHD_KitAtc(frame) or CHD_UniPanel(frame)
      CHD_Cmd(CHD.NODE_POS, frame, 0, CHD.ATC_UNI, 0, k[1])
      CHD_Cmd(CHD.NODE_POS, frame, 0, CHD.ATC_UNI, 1, k[2])
    end
  end
end

-- a plate is there once its layer is open and not hidden. The bar opens the kit and the plates in one OnOpenLayer,
-- but the plates (fonts) finish loading / become visible a few Steps after the kit: in game (1.6.0) the first Step
-- with the bar and the kit open still saw no team name plate on every dock, so a missing plate only counts once it
-- is still missing after CHD_PLATE_WAIT Steps
local CHD_PLATE_WAIT = 120
local function CHD_Plate(layer)
  local open = CHD_Open(layer, 0)
  local vis = open and CHD_Get(CHD.IS_VISIBLE, layer, 0) ~= false
  return open and vis, open
end

local function CHD_Decide()
  if CHD.hdr ~= nil or not CHD_Open(CHD.BAR, 0) or not CHD_Open(CHD.UNI, 0) then
    return
  end
  if rawget(_ENV, "g_parentMenuId") == CHD.VR_MENU then
    CHD_SetMode("panel", "opened from the Victory Road")
    return
  end
  if CHD.headerOff == nil then
    local f = type(VRFW_TeamEditor) == "table" and type(VRFW_TeamEditor.Foreign) == "function"
      and VRFW_TeamEditor.Foreign() or nil
    CHD.headerOff = type(f) == "table" and f.header == false
  end
  if CHD.headerOff then
    CHD_SetMode("panel", "the team editor's host hides the team name bar")
    return
  end
  local name, nameOpen = CHD_Plate(CHD.NAME)
  local deck, deckOpen = CHD_Plate(CHD.DECK)
  if name and deck then
    CHD_SetMode("header", "crest | team name | kit | player plate | Nv., after " .. CHD.wait .. " Step(s)")
    CHD.check = 30
    return
  end
  CHD.wait = CHD.wait + 1
  if CHD.wait < CHD_PLATE_WAIT then
    return                        -- not decided yet: the header stays retail meanwhile
  end
  if not name then
    CHD_SetMode("panel", "no team name plate after " .. CHD.wait .. " Steps (open " .. tostring(nameOpen) .. ")")
  else
    CHD_SetMode("panel", "no player plate after " .. CHD.wait .. " Steps (open " .. tostring(deckOpen) .. ")")
  end
end

-- the placed team name and player plates where this layout put them (global units, the bar's measured scale), logged
-- once 30 Steps after the header mode is set. Log only: the 1.6.0 guard fell back to the retail header when they
-- were off, but the plates are attached layers whose global positions lag the bar's by a frame, so the Step after
-- the relayout measured them exactly at their retail places (-542 / 176) on every dock (in game 2026-10-03 12:21)
local function CHD_Check()
  if CHD.check <= 0 or CHD.hdr ~= "header" then
    return
  end
  CHD.check = CHD.check - 1
  if CHD.check > 0 then
    return
  end
  local bx, by = CHD_G(CHD.BAR, 0, CHD.POS_BASE)
  local ex = CHD_G(CHD.BAR, 0, CHD_HDR.crest)
  local nx = CHD_G(CHD.NAME, 0, CHD.NAME_BASE)
  local dx = CHD_G(CHD.DECK, 0, CHD.DECK_BASE)
  if bx == nil or ex == nil or nx == nil or dx == nil then
    return                        -- not measurable: kept
  end
  local k = (ex - bx) / CHD_BAR_CREST[1]
  if math.abs(k) < 0.05 then
    return
  end
  local en, ed = (nx - bx) / k, (dx - bx) / k
  CHD_Log(string.format("header measured: team name %.0f / player plate %.0f (layout %.0f / %.0f)",
    en, ed, CHD_HDR_CHECK.name_l, CHD_HDR_CHECK.deck_l))
end

-- a pointer's group switch this layout re-routes: the engine moved the focus from -> to by itself; the focus goes on
-- to this layout's target on the next Step, only if it is still where the engine put it. The pad never gets here:
-- CHD.Pad moves it (no focus shift row left on these layers)
local function CHD_Redirect(sh)
  local f, fi, t, ti = sh[1], sh[2], sh[3], sh[4]
  if not CHD_Active(t) then
    return
  end
  -- the list hidden (VRFW_TeamEditor spec.hide_list): the first icon, else back
  if t == CHD.LIST and CHD.Icons().hide then
    CHD.OffList(t, ti, f, fi)
    return
  end
  local hdr = CHD.hdr == "header"
  if hdr and f == CHD.NAME and t == CHD.DECK and CHD_Open(CHD.UNI, 0) then
    CHD_Go(t, ti, CHD.UNI, 0)                 -- team name RIGHT -> kit
  elseif hdr and f == CHD.DECK and t == CHD.NAME and CHD_Open(CHD.UNI, 0) then
    CHD_Go(t, ti, CHD.UNI, 0)                 -- player plate LEFT -> kit
  elseif hdr and f == CHD.UNI and t == CHD.FORM then
    CHD_Go(t, ti, CHD.UNI, 0)                 -- kit UP: nothing above it in the header
  elseif hdr and f == CHD.UNI and t == CHD.CONF and CHD_Open(CHD.NAME, 0) then
    CHD_Go(t, ti, CHD.NAME, 0)                -- kit LEFT -> team name
  elseif f == CHD.FORM and t == CHD.TAC and CHD_TacOn() and CHD_Open(CHD.TAC, 2) then
    CHD_Go(t, ti, CHD.TAC, 2)                 -- FORMACIÓN UP -> left tactic box
  elseif f == CHD.FORM and t == CHD.CONF then
    if hdr then
      CHD_FormDown(t, ti)                     -- FORMACIÓN DOWN: the card below, else FORMACIÓN stays
    elseif CHD_Open(CHD.UNI, 0) then
      CHD_Go(t, ti, CHD.UNI, 0)               -- panel mode: the kit under the panel
    end
  elseif f == CHD.CONF and t == CHD.FORM and CHD_Open(CHD.TAC, 0) then
    CHD_Go(t, ti, CHD.TAC, 0)                 -- CONF. UP -> right tactic box
  elseif f == CHD.CONF and t == CHD.UNI then
    CHD_ConfToPitch(t, ti)                    -- CONF. RIGHT -> the pitch
  elseif f == CHD.TAC and t == CHD.FORM and fi == 0 and CHD_TacOn() and CHD_ConfShown() then
    CHD_Go(t, ti, CHD.CONF, 0)                -- right tactic box DOWN -> CONF.
  end
end

-- a pointer's group switch (0x535F80, OnMouseMove) ends in this callback and sets its focus after it, so the redirect
-- waits for the next Step
local chd_prev_shift = rawget(_ENV, "OnFocusLayerShift")
if type(chd_prev_shift) == "function" then
  rawset(_ENV, "OnFocusLayerShift", function(a1, a2, a3, a4, ...)
    local r = CHD_Pack(chd_prev_shift(a1, a2, a3, a4, ...))
    CHD.focusAt = a3              -- where the focus went (any shift: a key, the pointer, CHD_Go)
    if not CHD.going and CHD_PanelOn() then
      local sh = {a1, a2, a3, a4}
      if CHD.moves < 80 then
        CHD.moves = CHD.moves + 1
        CHD_Log("shift " .. tostring(a1) .. "[" .. tostring(a2) .. "] -> " .. tostring(a3) .. "[" .. tostring(a4) .. "]")
      end
      if a3 == CHD_SlotLayer() then
        CHD.shift = nil           -- onto another mod's picture button (the pointer): kept, with its help line
        CHD_SlotHelp(select(2, CHD_SlotLayer()))
      elseif a3 == CHD.ICON then
        CHD.shift = nil           -- onto an icon button (the pointer): kept, with its help line
        CHD.IconHelp(a4)
      elseif (a1 == CHD.FORM or a1 == CHD.CONF) and (a3 == CHD.FORM or a3 == CHD.CONF) and CHD.PointerOnBox(a3) then
        CHD.shift = nil           -- the pointer's group switch onto the box under it: not a key move, kept as it is
      else
        CHD.shift = sh
      end
      CHD.LockGuard(a1, a2)
    end
    return table.unpack(r, 1, r.n)
  end)
end

-- the focus landed on a fixed identity item (a key, the pointer or a redirect): back to `from` (another item)
function CHD.LockGuard(from, fi)
  local at = CHD.focusAt
  if not CHD.Locked() or at == nil or not CHD.LOCKED_LAYERS[at] or CHD.LOCKED_LAYERS[from] then
    return
  end
  CHD.shift = nil
  CHD_Go(at, 0, from, fi or 0)
end

CHD_After("Step", function()
  if CHD_PanelOn() and not CHD.busy then
    CHD_Decide()
    CHD_Check()
    if CHD.shift ~= nil then
      local sh = CHD.shift
      CHD.shift = nil
      CHD_Redirect(sh)
      CHD.LockGuard(sh[1], sh[2])
    end
    if CHD_ClipOn() then
      CHD_Clip()
    end
    CHD_FixKit()
    CHD.BoxGuard()
    CHD.HeaderFocusLog()
  end
  if not CHD.busy then
    CHD.HeaderZones()
  end
  if not CHD.busy then
    CHD_Atdf()
  end
  if not CHD.busy then
    CHD_SlotPlace()
    CHD.IconsPlace()
  end
  if not CHD.busy then
    CHD_Ghost()
  end
end)
